/**
 * A simple string utility module.
 */

/**
 * Reverses a string.
 */
export function reverse(s: string): string {
  return s.split('').reverse().join('');
}

/**
 * Capitalizes the first letter of a string.
 */
export function capitalize(s: string): string {
  if (s.length === 0) return s;
  return s[0].toUpperCase() + s.slice(1);
}

/**
 * Truncates a string to a given length, adding '...' if truncated.
 * @throws {Error} if maxLength is less than 4 (can't fit '...' + 1 char)
 */
export function truncate(s: string, maxLength: number): string {
  if (maxLength < 4) {
    throw new Error('maxLength must be at least 4');
  }
  if (s.length <= maxLength) return s;
  return s.slice(0, maxLength - 3) + '...';
}

/**
 * Checks if a string is a palindrome (case-insensitive).
 */
export function isPalindrome(s: string): boolean {
  const normalized = s.toLowerCase().replace(/[^a-z0-9]/g, '');
  return normalized === reverse(normalized);
}

import { describe, test, expect } from 'bun:test';
import { reverse, capitalize, truncate, isPalindrome } from '../src/index';

describe('string utilities', () => {
  test('reverse', () => {
    expect(reverse('hello')).toBe('olleh');
    expect(reverse('')).toBe('');
  });

  test('capitalize', () => {
    expect(capitalize('hello')).toBe('Hello');
    expect(capitalize('')).toBe('');
  });

  test('truncate', () => {
    expect(truncate('hello world', 8)).toBe('hello...');
    expect(truncate('hi', 10)).toBe('hi');
  });

  test('truncate throws on small maxLength', () => {
    expect(() => truncate('hello', 3)).toThrow('maxLength must be at least 4');
  });

  test('isPalindrome', () => {
    expect(isPalindrome('racecar')).toBe(true);
    expect(isPalindrome('A man a plan a canal Panama')).toBe(true);
    expect(isPalindrome('hello')).toBe(false);
  });
});

/**
 * Math utility functions.
 */

/**
 * Adds two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * Multiplies two numbers.
 */
export function multiply(a: number, b: number): number {
  return a * b;
}

/**
 * Computes the factorial of n.
 * NOTE: This implementation has a bug — it returns n instead of 1 for n=0.
 */
export function factorial(n: number): number {
  if (n < 0) throw new Error('n must be non-negative');
  if (n === 0) return n;  // BUG: should return 1
  return n * factorial(n - 1);
}

import { describe, test, expect } from 'bun:test';
import { add, multiply, factorial } from '../src/math';

describe('math utilities', () => {
  test('add', () => {
    expect(add(2, 3)).toBe(5);
    expect(add(-1, 1)).toBe(0);
  });

  test('multiply', () => {
    expect(multiply(3, 4)).toBe(12);
    expect(multiply(0, 5)).toBe(0);
  });

  test('factorial', () => {
    expect(factorial(0)).toBe(1);
    expect(factorial(1)).toBe(1);
    expect(factorial(5)).toBe(120);
  });

  test('factorial throws on negative', () => {
    expect(() => factorial(-1)).toThrow('n must be non-negative');
  });
});

