export function factorial(n: number): number {
  if (n < 0) throw new Error('n must be non-negative');
  if (n === 0) return 1;
  return n * factorial(n - 1);
}

/**
 * Email and URL validation utilities.
 */

/**
 * Validates an email address (basic check).
 */
export function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

/**
 * Validates a URL.
 */
export function isValidUrl(url: string): boolean {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
}

/**
 * Sanitizes a string by removing HTML tags.
 */
export function sanitize(input: string): string {
  return input.replace(/<[^>]*>/g, '');
}

import { describe, test, expect } from 'bun:test';
import { isValidEmail, isValidUrl, sanitize } from '../src/validator';

describe('validator', () => {
  test('isValidEmail', () => {
    expect(isValidEmail('user@example.com')).toBe(true);
    expect(isValidEmail('not-an-email')).toBe(false);
    expect(isValidEmail('')).toBe(false);
  });

  test('isValidUrl', () => {
    expect(isValidUrl('https://example.com')).toBe(true);
    expect(isValidUrl('not-a-url')).toBe(false);
  });

  test('sanitize', () => {
    expect(sanitize('<b>bold</b>')).toBe('bold');
