/**
 * Email and URL validation utilities.
 */

/**
 * Validates an email address (basic check).
 * @throws {TypeError} if input is not a string
 */
export function isValidEmail(email: string): boolean {
  if (typeof email !== 'string') {
    throw new TypeError('email must be a string');
  }
  if (email.length === 0 || email.length > 254) return false;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

/**
 * Validates a URL.
 * @throws {TypeError} if input is not a string
 */
export function isValidUrl(url: string): boolean {
  if (typeof url !== 'string') {
    throw new TypeError('url must be a string');
  }
  if (url.length === 0) return false;
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
}

/**
 * Sanitizes a string by removing HTML tags.
 * @throws {TypeError} if input is not a string
 */
export function sanitize(input: string): string {
  if (typeof input !== 'string') {
    throw new TypeError('input must be a string');
  }
  return input.replace(/<[^>]*>/g, '');
}

import { describe, test, expect } from 'bun:test';
import { isValidEmail, isValidUrl, sanitize } from '../src/validator';

describe('validator', () => {
  test('isValidEmail', () => {
    expect(isValidEmail('user@example.com')).toBe(true);
    expect(isValidEmail('not-an-email')).toBe(false);
    expect(isValidEmail('')).toBe(false);
  });

  test('isValidEmail rejects non-string', () => {
    expect(() => isValidEmail(42 as any)).toThrow('email must be a string');
    expect(() => isValidEmail(null as any)).toThrow('email must be a string');
  });

  test('isValidEmail rejects overlong input', () => {
    expect(isValidEmail('a'.repeat(255) + '@example.com')).toBe(false);
  });

  test('isValidUrl', () => {
    expect(isValidUrl('https://example.com')).toBe(true);
    expect(isValidUrl('not-a-url')).toBe(false);
    expect(isValidUrl('')).toBe(false);
  });

  test('isValidUrl rejects non-string', () => {
    expect(() => isValidUrl(123 as any)).toThrow('url must be a string');
  });

  test('sanitize', () => {
    expect(sanitize('<b>bold</b>')).toBe('bold');
    expect(sanitize('no tags')).toBe('no tags');
  });

  test('sanitize rejects non-string', () => {
    expect(() => sanitize(undefined as any)).toThrow('input must be a string');
  });
});

